#' Post hoc analysis for MANOVA (DDA)
#'
#' 
#' @param data .
#' @param dep .
#' @param covs .
#' @param prop .
#' @param coef .
#' @param structCoef .
#' @param gc .
#' @param classTable .
#' @param boxM .
#' @param plot .
#' @param showEllipse .
#' @param ellipseLevel .
#' @param width .
#' @param height .
#' @param discScores .
#' @param pairwiseES .
#' @return A results object containing:
#' \tabular{llllll}{
#'   \code{results$ddaInfo} \tab \tab \tab \tab \tab a html \cr
#'   \code{results$prop} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$coef} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$structCoefTable} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$gc} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$boxMTable} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$classTable} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$plot} \tab \tab \tab \tab \tab an image \cr
#'   \code{results$discScoresTable} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$pairwiseESTable} \tab \tab \tab \tab \tab a table \cr
#' }
#'
#' Tables can be converted to data frames with \code{asDF} or \code{\link{as.data.frame}}. For example:
#'
#' \code{results$prop$asDF}
#'
#' \code{as.data.frame(results$prop)}
#'
#' @export
DDA <- function(
    data,
    dep,
    covs,
    prop = FALSE,
    coef = TRUE,
    structCoef = TRUE,
    gc = TRUE,
    classTable = FALSE,
    boxM = FALSE,
    plot = FALSE,
    showEllipse = TRUE,
    ellipseLevel = 0.95,
    width = 500,
    height = 500,
    discScores = FALSE,
    pairwiseES = FALSE) {

    if ( ! requireNamespace("jmvcore", quietly=TRUE))
        stop("DDA requires jmvcore to be installed (restart may be required)")

    if ( ! missing(dep)) dep <- jmvcore::resolveQuo(jmvcore::enquo(dep))
    if ( ! missing(covs)) covs <- jmvcore::resolveQuo(jmvcore::enquo(covs))
    if (missing(data))
        data <- jmvcore::marshalData(
            parent.frame(),
            `if`( ! missing(dep), dep, NULL),
            `if`( ! missing(covs), covs, NULL))

    for (v in dep) if (v %in% names(data)) data[[v]] <- as.factor(data[[v]])

    options <- DDAOptions$new(
        dep = dep,
        covs = covs,
        prop = prop,
        coef = coef,
        structCoef = structCoef,
        gc = gc,
        classTable = classTable,
        boxM = boxM,
        plot = plot,
        showEllipse = showEllipse,
        ellipseLevel = ellipseLevel,
        width = width,
        height = height,
        discScores = discScores,
        pairwiseES = pairwiseES)

    analysis <- DDAClass$new(
        options = options,
        data = data)

    analysis$run()

    analysis$results
}

